<?php
namespace Tests\Feature;
use App\Models\{AuditLog,Club,ClubMembership,Member,ProfileUpdateRequest,Role,User};use Database\Seeders\DatabaseSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class Milestone3hbProfileUpdateRequestLifecycleWorkflowTest extends TestCase{use RefreshDatabase;
 public function test_all_roles_submit_own_and_validation_duplicate_and_audit():void{$this->seed(DatabaseSeeder::class);foreach(['president-admin','secretary','treasurer','member'] as $i=>$role){$c=$this->club('S'.$i);[$u,$m]=$this->actor($c,$role,'M'.$i);Sanctum::actingAs($u);$r=$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['phone'=>' 9000 '.$i.' ','occupation'=>'Teacher']])->assertCreated()->assertJsonPath('data.status','pending');$id=$r->json('data.id');$this->assertDatabaseHas('profile_update_requests',['id'=>$id,'member_id'=>$m->id,'requester_user_id'=>$u->id,'status'=>'pending']);$this->assertDatabaseHas('audit_logs',['action'=>'profile_updates.submitted','auditable_id'=>$id]);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['phone'=>'8']])->assertConflict();}$c=$this->club('V');[$u]=$this->actor($c,'member','V');Sanctum::actingAs($u);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['member_code'=>'X']])->assertUnprocessable();$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['member_id'=>99,'changes'=>['phone'=>'1']])->assertUnprocessable();$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['club_id'=>99,'changes'=>['phone'=>'1']])->assertUnprocessable();$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['phone'=>null]])->assertUnprocessable();}
 public function test_president_and_secretary_approve_exact_changes_and_stale_conflict():void{$this->seed(DatabaseSeeder::class);foreach(['president-admin','secretary'] as $role){$c=$this->club('A'.$role);[$memberUser,$m]=$this->actor($c,'member','M');[$reviewer]=$this->actor($c,$role,'R');Sanctum::actingAs($memberUser);$request=$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['occupation'=>'Engineer','phone'=>'777']])->assertCreated()->json('data');Sanctum::actingAs($reviewer);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$request['id']}/approve",['lock_version'=>$request['lock_version']])->assertOk()->assertJsonPath('data.status','approved');$m->refresh();$this->assertSame('Engineer',$m->occupation);$this->assertSame('777',$m->phone);$this->assertDatabaseHas('audit_logs',['action'=>'profile_updates.approved','auditable_id'=>$request['id']]);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$request['id']}/approve",['lock_version'=>2])->assertConflict();}
 $c=$this->club('STALE');[$memberUser,$m]=$this->actor($c,'member','S');[$president]=$this->actor($c,'president-admin','P');Sanctum::actingAs($memberUser);$r=$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['occupation'=>'New']])->assertCreated()->json('data');$m->update(['occupation'=>'Intervening']);Sanctum::actingAs($president);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$r['id']}/approve",['lock_version'=>1])->assertConflict();$this->assertSame('Intervening',$m->refresh()->occupation);$this->assertDatabaseHas('profile_update_requests',['id'=>$r['id'],'status'=>'pending']);$this->assertDatabaseHas('audit_logs',['action'=>'profile_updates.stale_conflict','auditable_id'=>$r['id']]);}
 public function test_reject_withdraw_permissions_terminal_and_no_member_mutation():void{$this->seed(DatabaseSeeder::class);$c=$this->club('RW');[$u,$m]=$this->actor($c,'member','M');[$president]=$this->actor($c,'president-admin','P');[$treasurer]=$this->actor($c,'treasurer','T');Sanctum::actingAs($u);$r=$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['occupation'=>'Rejected']])->assertCreated()->json('data');Sanctum::actingAs($treasurer);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$r['id']}/reject",['lock_version'=>1,'reason'=>'No'])->assertForbidden();Sanctum::actingAs($president);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$r['id']}/reject",['lock_version'=>1,'reason'=>'Need supporting correction'])->assertOk()->assertJsonPath('data.status','rejected');$this->assertNull($m->refresh()->occupation);$this->assertDatabaseHas('audit_logs',['action'=>'profile_updates.rejected','auditable_id'=>$r['id']]);Sanctum::actingAs($u);$r2=$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['occupation'=>'Withdrawn']])->assertCreated()->json('data');Sanctum::actingAs($president);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$r2['id']}/withdraw",['lock_version'=>1])->assertForbidden();Sanctum::actingAs($u);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$r2['id']}/withdraw",['lock_version'=>1])->assertOk()->assertJsonPath('data.status','withdrawn');$this->assertNull($m->refresh()->occupation);$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests/{$r2['id']}/withdraw",['lock_version'=>2])->assertConflict();$this->assertDatabaseHas('audit_logs',['action'=>'profile_updates.withdrawn','auditable_id'=>$r2['id']]);}

 public function test_changed_file_scope_is_lifecycle_safe():void{$r=dirname(__DIR__,3);$subject='Add profile update request workflows';exec('git -C "'.$r.'" log --all --format=%H%x09%s',$logs,$code);$this->assertSame(0,$code);$matches=[];foreach($logs as $line){[$h,$s]=array_pad(explode("	",$line,2),2,'');if($s===$subject)$matches[]=$h;}if($matches){exec('git -C "'.$r.'" diff-tree --no-commit-id --name-only -r '.$matches[0],$files,$status);$this->assertSame(0,$status);}else{$this->assertSame('ac6b6d43b63791c94e29c8d597cde187ccf7920a',trim(shell_exec('git -C "'.$r.'" rev-parse HEAD')));exec('git -C "'.$r.'" status --porcelain=v1 -uall',$raw,$status);$files=array_map(fn($x)=>str_replace('\\','/',substr($x,3)),$raw);}$allowed=['backend/tests/Feature/AuthMeRoleAwareResponseTest.php','backend/app/Http/Controllers/Api/V1/ProfileUpdates/ProfileUpdateRequestController.php','backend/app/Http/Requests/ProfileUpdates/RejectProfileUpdateRequest.php','backend/app/Http/Requests/ProfileUpdates/StoreProfileUpdateRequest.php','backend/app/Http/Requests/ProfileUpdates/TransitionProfileUpdateRequest.php','backend/app/Services/ProfileUpdates/ProfileUpdateWriteService.php','backend/docs/milestone_3hb_profile_update_request_lifecycle_workflow.md','backend/routes/api.php','backend/tests/Feature/Milestone3haProfileUpdateRequestDatabaseReadFoundationTest.php','backend/tests/Feature/Milestone3hbProfileUpdateRequestLifecycleWorkflowTest.php'];sort($files);sort($allowed);$this->assertSame($allowed,$files);}
 private function club($x):Club{return Club::create(['name'=>$x,'code'=>$x.uniqid(),'timezone'=>'Asia/Kolkata','is_active'=>true]);}private function actor($c,$role,$code):array{$u=User::factory()->create();ClubMembership::create(['club_id'=>$c->id,'user_id'=>$u->id,'role_id'=>Role::where('slug',$role)->firstOrFail()->id,'status'=>'active','joined_at'=>now()]);$m=Member::create(['club_id'=>$c->id,'user_id'=>$u->id,'member_code'=>$code.uniqid(),'full_name'=>'Duplicate Member','status'=>'active']);return[$u,$m];}}
